const json = (file, value) => writeFile(file, JSON.stringify(value, null, 2) + '\n');
const additions = {
  before: {title: ' · 保存前补记', body: '\n\n保存前补记：林澈把观察时间写在页边。'},
  post: {title: '【POST等待输入】', body: '\nPOST等待输入：周伯仍站在窗边。'},
