  for (const check of checks) console.log(`${check.category} ${check.skipped ? '待定' : check.passed ? '通过' : '失败'}：${check.name}`);
  // 两个结果分别尝试写入；磁盘失败照样使 node:test 非零，不冒充业务红。
  for (const name of ['evidence.json', 'result.json']) {
